using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Creezio.Switcher;

internal static class PortalSkillTests
{
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]private static extern bool CreateHardLink(string file,string existing,IntPtr security);
    private static void Assert(bool condition,string message){if(!condition)throw new Exception(message);}
    private static object Normal(object value){return Json.Read<object>(Json.Write(value));}
    private static string Text(object value,string field){return Json.Str(Json.Get(Normal(value),field));}
    private static object[] Rows(object value){return RelayEngine.Rows(Json.Get(Normal(value),"skills")).ToArray();}
    private static object Skill(object value){return Json.Get(Normal(value),"skill");}
    private static void Reject(Action call,int status=0){try{call();}catch(WebhookException error){if(status==0||error.StatusCode==status)return;throw;}throw new Exception("Expected a bounded scoped refusal");}
    private static string Document(string name,string body="Do the requested fictional operation."){return "---\nname: "+name+"\ndescription: A fictional skill used only in isolated tests.\n---\n\n"+body+"\n";}
    private static string Zip(Dictionary<string,byte[]> files,Action<ZipArchiveEntry> annotate=null)
    {using(var output=new MemoryStream()){using(var archive=new ZipArchive(output,ZipArchiveMode.Create,true)){foreach(var file in files){var entry=archive.CreateEntry(file.Key,CompressionLevel.Optimal);if(annotate!=null)annotate(entry);using(var stream=entry.Open())stream.Write(file.Value,0,file.Value.Length);}}return Convert.ToBase64String(output.ToArray());}}
    private static Dictionary<string,byte[]> Files(string name,string prefix=""){return new Dictionary<string,byte[]>{{prefix+"SKILL.md",Encoding.UTF8.GetBytes(Document(name))},{prefix+"references/example.txt",Encoding.UTF8.GetBytes("fictional supporting reference")}};}
    private sealed class Fixture:IDisposable
    {
        internal readonly string Route=new string('a',32),Actor=new string('b',64),Instance=new string('c',32),Other=new string('d',32),Root,Home,OtherHome;
        internal RelayStore Store;internal PortalSkillService Service;internal PortalSkillDependencies Dependencies;internal bool Allowed=true,OtherAllowed=true;
        internal string Account="fictional-account",OtherAccount="fictional-other-account";internal long Revision=1;internal int Authorizations;
        internal Fixture(string sandbox){Root=Path.Combine(sandbox,"s"+Guid.NewGuid().ToString("N").Substring(0,6));Home=Path.Combine(Root,"h");OtherHome=Path.Combine(Root,"o");Directory.CreateDirectory(Home);Directory.CreateDirectory(OtherHome);Store=new RelayStore(Path.Combine(Root,"r"));
            Dependencies=new PortalSkillDependencies{SharedSkillsRoot=Path.Combine(Root,"shared"),BuiltinSkillsRoot=Path.Combine(Root,"builtins"),Resolve=(route,actor,instance)=>{
                if(instance==Other&&!OtherAllowed)throw new WebhookException(403,"Fictional source grant revoked");
                return new PortalSkillTarget{InstanceId=instance,Home=instance==Other?OtherHome:Home,AccountKey=instance==Other?OtherAccount:Account,GrantRevision=Revision,PolicyRevision=1,SiteOrigin="https://fictional.example.invalid"};}};
            Service=new PortalSkillService(Store,(route,actor)=>{Authorizations++;if(!Allowed||route!=Route||actor!=Actor)throw new WebhookException(403,"Fictional actor revoked");},Dependencies);
        }
        internal object Catalog(string instance=null){return Normal(Service.Catalog(Route,Actor,instance??Instance));}
        internal object Save(string name,string key="create",string document=null,string source=null,string expected=null,string instance=null)
        {return Normal(Service.Save(Route,Actor,instance??Instance,key,new PortalSkillSaveRequest{Name=name,Document=document??Document(name),SourceSkillId=source,ExpectedRevision=expected}));}
        internal object Import(string name,string archive,string key="import",string expected=null){return Normal(Service.Import(Route,Actor,Instance,key,new PortalSkillImportRequest{Name=name,ArchiveBase64=archive,ExpectedRevision=expected}));}
        internal object Deploy(object row,string target=null,string key="deploy",string expected=null)
        {return Normal(Service.Deploy(Route,Actor,target??Other,key,new PortalSkillDeployRequest{SourceInstanceId=Instance,SkillId=Text(row,"id"),SourceRevision=Text(row,"revision"),Name=Text(row,"name"),ExpectedRevision=expected}));}
        internal string Seed(string parent,string name,string document=null){string folder=Path.Combine(parent,name);Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"SKILL.md"),document??Document(name),new UTF8Encoding(false));return folder;}
        internal string Plugin(string name="delegate-task")
        {string parent=Path.Combine(Home,"plugins","cache","creezio-switcher","creezio-relay","test-v1","skills");Store.WriteRecord("integration-"+RelayIntegration.HomeKey(Home)+".dpapi",new RelayIntegrationState{InstalledVersion="test-v1"});return Seed(parent,name);}
        public void Dispose(){}
    }
    internal static void RunAll(Action<string,Action> check,string sandbox)
    {
        check("skills catalog includes the four installed relay skills, system and shared sources without launching a process",()=>{
            using(var f=new Fixture(sandbox)){foreach(string name in new[]{"delegate-task","execute-relay-task","request-assistance","use-shared-tools"})f.Plugin(name);f.Seed(Path.Combine(f.Home,"skills",".system"),"skill-creator");f.Seed(f.Dependencies.SharedSkillsRoot,"shared-example");
                var rows=Rows(f.Catalog());Assert(rows.Length==6&&rows.Count(r=>Text(r,"origin")=="plugin")==4,"Installed relay skills disappeared");Assert(rows.Where(r=>Text(r,"origin")!="user"||Text(r,"scope")=="shared").All(r=>Object.Equals(Json.Get(r,"editable"),false)),"Immutable source was editable");Assert(f.Authorizations>=2,"Catalog did not revalidate actor");}
        });
        check("skills local primary source is explicitly supported while remote calls still require administration",()=>{
            using(var f=new Fixture(sandbox)){f.Allowed=false;var result=f.Service.SaveLocal("local","desktop",new PortalSkillSaveRequest{Name="local-example",Document=Document("local-example")});Assert(Text(result,"state")=="deployed"&&Rows(f.Service.CatalogLocal("local")).Length==1,"Primary source unavailable");Reject(()=>f.Catalog(),403);}
        });
        check("skills creation is immediately discoverable and uses native composer opaque IDs with idempotent receipts",()=>{
            using(var f=new Fixture(sandbox)){var first=f.Save("my-example");var row=Skill(first);string path=Path.Combine(f.Home,"skills","my-example","SKILL.md");Assert(Text(row,"id")==ToolTunnel.Hash(new{kind="skill",name="my-example",path=path}),"ID diverged from native composer");Assert(Text(row,"revision").Length==64&&Text(first,"state")=="deployed","Missing deployment receipt");var again=f.Save("my-example");Assert(Text(first,"operationId")==Text(again,"operationId")&&Rows(f.Catalog()).Length==1,"Retry duplicated a skill");Reject(()=>f.Save("my-example",document:Document("my-example","A changed request.")),409);Assert(Object.Equals(Json.Get(first,"refreshRequired"),true),"No honest reload indication");}
        });
        check("skills read and edit preserve supporting assets and reject stale revisions",()=>{
            using(var f=new Fixture(sandbox)){var imported=f.Import("asset-example",Zip(Files("asset-example")));var row=Skill(imported);string asset=Path.Combine(f.Home,"skills","asset-example","references","example.txt"),assetBefore=File.ReadAllText(asset);var detail=Normal(f.Service.Read(f.Route,f.Actor,f.Instance,Text(row,"id")));Assert(Text(detail,"document").Contains("asset-example")&&RelayEngine.Rows(Json.Get(detail,"files")).Count()==2,"Read omitted document or asset metadata");var changed=f.Save("asset-example","edit",Document("asset-example","Changed instructions."),Text(row,"id"),Text(row,"revision"));Assert(Text(Skill(changed),"revision")!=Text(row,"revision")&&File.ReadAllText(asset)==assetBefore,"Edit lost assets");Reject(()=>f.Save("asset-example","stale",Document("asset-example"),Text(row,"id"),Text(row,"revision")),409);}
        });
        check("skills plugin customization copies resources into the instance and never edits the original plugin cache",()=>{
            using(var f=new Fixture(sandbox)){string plugin=f.Plugin();Directory.CreateDirectory(Path.Combine(plugin,"references"));File.WriteAllText(Path.Combine(plugin,"references","native.txt"),"original reference");string original=File.ReadAllText(Path.Combine(plugin,"SKILL.md"));var row=Rows(f.Catalog()).Single();var customized=f.Save("delegate-task","customize",Document("delegate-task","Personal instructions."),Text(row,"id"),Text(row,"revision"));Assert(File.ReadAllText(Path.Combine(plugin,"SKILL.md"))==original&&File.ReadAllText(Path.Combine(f.Home,"skills","delegate-task","references","native.txt"))=="original reference","Plugin source changed or assets disappeared");Assert(Text(Skill(customized),"origin")=="user"&&Text(Skill(customized),"overridesId")==Text(row,"id")&&Rows(f.Catalog()).Length==2&&Text(customized,"message").Contains("explicitement"),"Customization origin or honest invocation guidance missing");var copy=Skill(customized);var edited=f.Save("delegate-task","edit-copy",Document("delegate-task","Second personal instructions."),Text(copy,"id"),Text(copy,"revision"));Assert(Text(Skill(edited),"overridesId")==Text(row,"id")&&!Text(edited,"message").StartsWith("Copie"),"Editing lost original provenance or falsely claimed a second copy");}
        });
        check("skills imported zip supports one outer folder and rejects unsafe paths, duplicate names and symbolic links",()=>{
            using(var f=new Fixture(sandbox)){var good=f.Import("wrapped-example",Zip(Files("wrapped-example","wrapper/")));Assert(Text(good,"state")=="deployed","Conventional archive wrapper rejected");int index=0;foreach(string path in new[]{"../escape.txt","x/../../escape.txt","/root.txt","a\\b.txt","x:stream","CON.txt","COM\u00b9.txt","CONIN$","x./file",".env",".env.local","auth.json","x/config.toml"}){var files=Files("unsafe-example");files[path]=new byte[]{1};Reject(()=>f.Import("unsafe-example",Zip(files),"bad"+(index++)),400);}var duplicate=Files("duplicate-example");duplicate["skill.md"]=new byte[]{1};Reject(()=>f.Import("duplicate-example",Zip(duplicate),"duplicate"),400);Reject(()=>f.Import("symlink-example",Zip(Files("symlink-example"),entry=>entry.ExternalAttributes=unchecked((int)0xA1FF0000)),"link"),400);Assert(!File.Exists(Path.Combine(f.Root,"escape.txt")),"Traversal escaped sandbox");}
        });
        check("skills zip and source validation enforce expanded file limits and strict UTF8 frontmatter",()=>{
            using(var f=new Fixture(sandbox)){var huge=Files("large-example");huge["assets/huge.bin"]=new byte[PortalSkillService.MaximumFile+1];Reject(()=>f.Import("large-example",Zip(huge),"large"),400);var invalid=Files("utf-example");invalid["SKILL.md"]=new byte[]{255,254,253};Reject(()=>f.Import("utf-example",Zip(invalid),"utf"),400);foreach(string document in new[]{Document("different-name"),"No frontmatter","---\nname: valid-name\nname: valid-name\ndescription: text\n---\nBody",Document("valid-name").Replace("description:","description: !include "),Document("valid-name").Replace("description:","unknown: field\ndescription:")})Reject(()=>f.Save("valid-name","invalid"+Guid.NewGuid().ToString("N"),document),400);Assert(!Directory.Exists(Path.Combine(f.Home,"skills","valid-name")),"Invalid frontmatter was deployed");}
        });
        check("skills deployment checks both instance grants and pins the source account until commit",()=>{
            using(var f=new Fixture(sandbox)){var row=Skill(f.Save("deploy-example"));f.OtherAllowed=false;Reject(()=>f.Deploy(row),403);f.OtherAllowed=true;f.Dependencies.BeforeCommit=()=>f.Account="foreign-account";Reject(()=>f.Deploy(row),409);Assert(!Directory.Exists(Path.Combine(f.OtherHome,"skills","deploy-example")),"Source account drift reached target");}
        });
        check("skills deployment detects asset source drift, target identity drift and revoked administration",()=>{
            using(var f=new Fixture(sandbox)){var row=Skill(f.Save("drift-example"));f.Dependencies.BeforeCommit=()=>File.WriteAllText(Path.Combine(f.Home,"skills","drift-example","SKILL.md"),Document("drift-example","Changed outside editor."));Reject(()=>f.Deploy(row),409);Assert(!Directory.Exists(Path.Combine(f.OtherHome,"skills","drift-example")),"Changed source deployed");}
            using(var f=new Fixture(sandbox)){f.Dependencies.BeforeCommit=()=>f.Account="foreign-account";Reject(()=>f.Save("target-example"),409);Assert(!Directory.Exists(Path.Combine(f.Home,"skills","target-example")),"Foreign target written");}
            using(var f=new Fixture(sandbox)){f.Dependencies.BeforeCommit=()=>f.Allowed=false;Reject(()=>f.Save("revoked-example"),403);Assert(!Directory.Exists(Path.Combine(f.Home,"skills","revoked-example")),"Revoked actor deployed");}
        });
        check("skills cross instance deployment preserves source bytes and explicit replacement requires current target revision",()=>{
            using(var f=new Fixture(sandbox)){var row=Skill(f.Save("copy-example"));string before=File.ReadAllText(Path.Combine(f.Home,"skills","copy-example","SKILL.md"));var deployed=f.Deploy(row);Assert(Text(deployed,"state")=="deployed"&&File.ReadAllText(Path.Combine(f.OtherHome,"skills","copy-example","SKILL.md"))==before,"Copy failed");Reject(()=>f.Deploy(row,key:"no-replace"),409);var repeated=f.Deploy(row,key:"replace",expected:Text(Skill(deployed),"revision"));Assert(Text(repeated,"state")=="deployed"&&File.ReadAllText(Path.Combine(f.Home,"skills","copy-example","SKILL.md"))==before,"Explicit revision replacement changed source");}
        });
        check("skills interrupted prepared transaction resumes the same operation without duplicate writes",()=>{
            using(var f=new Fixture(sandbox)){f.Dependencies.BeforeCommit=()=>{throw new IOException("fictional storage interruption");};try{f.Save("resume-example");throw new Exception("Expected interruption");}catch(IOException){}Assert(!Directory.Exists(Path.Combine(f.Home,"skills","resume-example")),"Interrupted preparation was published");f.Dependencies.BeforeCommit=null;var resumed=f.Save("resume-example");Assert(Text(resumed,"state")=="deployed"&&Directory.GetDirectories(Path.Combine(f.Home,"skills")).Length==1,"Prepared operation did not resume");Assert(Directory.GetFileSystemEntries(Path.Combine(f.Home,".switcher-skill-stage")).Length==0,"Owned stage leaked after success");}
        });
        check("skills concurrent identical requests cannot publish twice and the loser can safely read the same receipt",()=>{
            using(var f=new Fixture(sandbox))using(var entered=new ManualResetEventSlim())using(var release=new ManualResetEventSlim()){
                f.Dependencies.BeforeCommit=()=>{entered.Set();Assert(release.Wait(5000),"Fictional commit barrier timeout");};var first=Task.Run(()=>f.Save("concurrent-example"));Assert(entered.Wait(5000),"First writer did not reach commit");var second=Task.Run(()=>f.Save("concurrent-example"));release.Set();var a=first.GetAwaiter().GetResult();var b=second.GetAwaiter().GetResult();Assert(Text(a,"operationId")==Text(b,"operationId")&&Rows(f.Catalog()).Length==1,"Concurrent requests duplicated deployment");}
        });
        check("skills names, request identities and scope cannot select arbitrary paths or another instance's source",()=>{
            using(var f=new Fixture(sandbox)){foreach(string name in new[]{"../bad","a/b","Bad","a--b","-bad","bad-","con","aux","com1","lpt9",new string('a',65)})Reject(()=>f.Save(name),400);var row=Skill(f.Save("scoped-example"));Reject(()=>f.Service.Read(f.Route,f.Actor,f.Other,Text(row,"id")),404);Reject(()=>f.Service.Catalog(f.Route,f.Actor,"../escape"),400);Reject(()=>f.Save("key-example",key:"bad\nkey"),400);}
        });
        check("skills catalogue includes malformed sources as visible diagnostics and honors disabled plugins",()=>{
            using(var f=new Fixture(sandbox)){f.Plugin();File.WriteAllText(Path.Combine(f.Home,"config.toml"),"[plugins.\"creezio-relay@creezio-switcher\"]\nenabled = false\n");f.Seed(Path.Combine(f.Home,"skills"),"broken-example","This file is not a skill frontmatter.");var rows=Rows(f.Catalog());Assert(rows.Length==2&&rows.Any(r=>Text(r,"name")=="broken-example"&&Text(r,"issue").Length>0&&!Object.Equals(Json.Get(r,"editable"),true)),"Malformed source silently vanished");Assert(!Object.Equals(Json.Get(rows.Single(r=>Text(r,"origin")=="plugin"),"enabled"),true),"Disabled plugin claimed enabled");}
        });
        check("skills plugin fallback exposes the four shipped skills even before integration is installed",()=>{
            using(var f=new Fixture(sandbox)){foreach(string name in new[]{"delegate-task","execute-relay-task","request-assistance","use-shared-tools"})f.Seed(f.Dependencies.BuiltinSkillsRoot,name);var rows=Rows(f.Catalog());Assert(rows.Length==4&&rows.All(r=>!Object.Equals(Json.Get(r,"installed"),true)&&Text(r,"scope")=="bundled"),"Shipped skills unavailable or falsely installed");}
        });
        check("skills installed mixed case names remain readable and can be customized under a valid user name",()=>{
            using(var f=new Fixture(sandbox)){string folder=f.Plugin("presentations");File.WriteAllText(Path.Combine(folder,"SKILL.md"),Document("Presentations"));var row=Rows(f.Catalog()).Single();Assert(Text(row,"name")=="Presentations"&&Text(row,"revision").Length==64,"Native mixed case name was treated as malformed");var detail=f.Service.Read(f.Route,f.Actor,f.Instance,Text(row,"id"));Assert(Text(detail,"document").Contains("name: Presentations"),"Original source not readable");var customized=f.Save("my-presentations","custom-case",Document("my-presentations"),Text(row,"id"),Text(row,"revision"));Assert(Text(Skill(customized),"name")=="my-presentations"&&File.ReadAllText(Path.Combine(folder,"SKILL.md")).Contains("name: Presentations"),"Mixed case source could not be customized safely");}
        });
        check("skills oversized package and malformed source stay visible and their document can be inspected without copying assets",()=>{
            using(var f=new Fixture(sandbox)){string folder=f.Plugin("big-example");Directory.CreateDirectory(Path.Combine(folder,"assets"));using(var stream=File.Create(Path.Combine(folder,"assets","large.bin")))stream.SetLength(PortalSkillService.MaximumFile+1);f.Seed(Path.Combine(f.Home,"skills"),"malformed-example","Original malformed source text.");var rows=Rows(f.Catalog());Assert(rows.Length==2&&rows.All(r=>Text(r,"revision").Length==0),"Unsafe package was offered for copy");foreach(var row in rows){var detail=f.Service.Read(f.Route,f.Actor,f.Instance,Text(row,"id"));Assert(Text(detail,"document").Length>0,"Source document disappeared behind package copy limits");}}
        });
        check("skills unregistered cache sources are visible without claiming active installation or enablement",()=>{
            using(var f=new Fixture(sandbox)){f.Seed(Path.Combine(f.Home,"plugins","cache","fictional-market","fictional-plugin","v1","skills"),"cached-example");var row=Rows(f.Catalog()).Single();Assert(Text(row,"scope")=="cache"&&!Object.Equals(Json.Get(row,"installed"),true)&&!Object.Equals(Json.Get(row,"enabled"),true)&&Text(row,"issue").Length>0,"Unregistered cache was promoted into an active installed skill");}
        });
        check("skills interrupted replacement after old directory move recovers only its own verified backup",()=>{
            using(var f=new Fixture(sandbox)){var row=Skill(f.Save("atomic-example"));f.Dependencies.BeforeCommit=()=>{throw new IOException("fictional interruption");};try{f.Save("atomic-example","atomic-edit",Document("atomic-example","New instructions."),Text(row,"id"),Text(row,"revision"));throw new Exception("Expected interruption");}catch(IOException){}
                string operation=Webhooks.Hash("skill-v1\n"+f.Route+"\n"+f.Actor+"\n"+f.Instance+"\natomic-edit").Substring(0,32),stage=Path.Combine(f.Home,".switcher-skill-stage",operation),target=Path.Combine(f.Home,"skills","atomic-example");Directory.Move(target,stage+"-backup");f.Dependencies.BeforeCommit=null;
                var recovered=f.Save("atomic-example","atomic-edit",Document("atomic-example","New instructions."),Text(row,"id"),Text(row,"revision"));Assert(Text(recovered,"state")=="deployed"&&File.ReadAllText(Path.Combine(target,"SKILL.md")).Contains("New instructions.")&&!Directory.Exists(stage+"-backup"),"Verified interrupted replacement did not recover");}
        });
        check("skills direct replacement rechecks the existing target after preparation before moving it",()=>{
            using(var f=new Fixture(sandbox)){var row=Skill(f.Save("replace-example"));string target=Path.Combine(f.Home,"skills","replace-example","SKILL.md");f.Dependencies.BeforeCommit=()=>File.WriteAllText(target,Document("replace-example","External newer edit."));Reject(()=>f.Import("replace-example",Zip(Files("replace-example")),"replace-race",Text(row,"revision")),409);Assert(File.ReadAllText(target).Contains("External newer edit."),"Import overwrote a concurrent external edit");}
        });
        check("skills hardlinked documents are neither disclosed nor copied and external source bytes stay intact",()=>{
            using(var f=new Fixture(sandbox)){string outside=Path.Combine(f.Root,"unrelated-private-fixture.txt"),folder=Path.Combine(f.Home,"skills","linked-example");File.WriteAllText(outside,"Fictional unrelated private content, never an actual credential.");Directory.CreateDirectory(folder);Assert(CreateHardLink(Path.Combine(folder,"SKILL.md"),outside,IntPtr.Zero),"Fictional hardlink setup failed");var row=Rows(f.Catalog()).Single();Assert(Text(row,"revision").Length==0&&Text(row,"issue").Length>0,"Linked source was admitted");bool refused=false;try{f.Service.Read(f.Route,f.Actor,f.Instance,Text(row,"id"));}catch(IOException){refused=true;}Assert(refused&&File.ReadAllText(outside).StartsWith("Fictional unrelated"),"Linked private content was exposed or changed");}
        });
        check("skills archive rejects a forged EOCD entry count before ZipArchive can materialize the central directory",()=>{
            using(var f=new Fixture(sandbox)){byte[] bytes=Convert.FromBase64String(Zip(Files("forged-example")));int end=bytes.Length-22;Assert(BitConverter.ToUInt32(bytes,end)==0x06054b50u,"Fixture EOCD missing");bytes[end+8]=1;bytes[end+9]=0;bytes[end+10]=1;bytes[end+11]=0;Reject(()=>f.Import("forged-example",Convert.ToBase64String(bytes),"forged"),400);Assert(!Directory.Exists(Path.Combine(f.Home,"skills","forged-example")),"Forged archive deployed");}
        });
        check("skills frontmatter preserves standard nested metadata and rejects malformed optional YAML before publication",()=>{
            using(var f=new Fixture(sandbox)){string valid="---\nname: yaml-example\ndescription: >\n  A fictional task with a folded\n  description.\nmetadata:\n  short-description: 'A user''s task'\n  options:\n    enabled: true\nlicense: Apache-2.0\nallowed-tools: [\"Read\", \"Grep\"]\n---\n\nFollow the fictional task.\n";var saved=f.Save("yaml-example","yaml-valid",valid);Assert(Text(saved,"state")=="deployed"&&File.ReadAllText(Path.Combine(f.Home,"skills","yaml-example","SKILL.md"))==valid,"Valid native metadata was changed or refused");foreach(string extra in new[]{"metadata: [unterminated","metadata:\n  key: one\n  key: two","metadata:\n  key: [unterminated","license: 'unterminated","license: Apache-2.0\n  stray: indentation"}){string invalid=Document("bad-yaml-example").Replace("\n---\n\n","\n"+extra+"\n---\n\n");Reject(()=>f.Save("bad-yaml-example",Guid.NewGuid().ToString("N"),invalid),400);}Assert(!Directory.Exists(Path.Combine(f.Home,"skills","bad-yaml-example")),"Malformed optional YAML reached the instance");}
        });
        check("skills native documents above 64 KiB remain readable while new writes and imports keep the 64 KiB cap",()=>{
            using(var f=new Fixture(sandbox)){string folder=f.Plugin("spreadsheets"),large=Document("Spreadsheets",new string('x',73000));File.WriteAllText(Path.Combine(folder,"SKILL.md"),large,new UTF8Encoding(false));var row=Rows(f.Catalog()).Single();Assert(Text(row,"name")=="Spreadsheets"&&Text(row,"revision").Length==64,"Large native metadata vanished");var detail=f.Service.Read(f.Route,f.Actor,f.Instance,Text(row,"id"));Assert(Text(detail,"document")==large,"Native document was truncated or refused");Reject(()=>f.Save("large-new-example","large-write",Document("large-new-example",new string('x',73000))),400);var files=Files("large-new-example");files["SKILL.md"]=Encoding.UTF8.GetBytes(Document("large-new-example",new string('x',73000)));Reject(()=>f.Import("large-new-example",Zip(files),"large-import"),400);var copied=f.Save("my-spreadsheets","short-customization",Document("my-spreadsheets"),Text(row,"id"),Text(row,"revision"));Assert(Text(copied,"state")=="deployed"&&File.ReadAllText(Path.Combine(folder,"SKILL.md"))==large,"Trimmed customization changed native original");}
        });
    }
}
